use vstd::prelude::*;

verus! {
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0,
            n >= 0,
        ensures
            new_list.len() == list.len(),
            forall(|i: usize| i < list.len() ==> new_list[i] == list[(i + (n % list.len())) % list.len()]),
    {
        let len = list.len();
        let s = len - (n % len);
        let mut new_list: Vec<u32> = Vec::new();
        new_list.resize(len, 0); // Initialize new_list with the same length as list

        // Fill new_list with the rotated values
        let mut i: usize = 0;
        while i < len
            invariant
                i <= len,
                new_list.len() == len,
                forall(|j: usize| j < i ==> new_list[j] == list[(j + (n % len)) % len]),
            decreases len - i,
        {
            if i < s {
                new_list[i] = list[i + (len - s)];
            } else {
                new_list[i] = list[i - s];
            }
            i = i + 1;
        }
        new_list
    }
}
